struct FTPCredentialChoice {let password:String}
enum FTPPassword {
 static func makePrompt(_ session:Session)->(alert:NSAlert,field:NSSecureTextField) {
  let alert=NSAlert();alert.messageText="连接 "+session.name
  alert.informativeText=session.connectionSummary+"\n"+(session.ftp?.security == .plain ? "FTP 会明文传输密码和文件。" : "FTPS 会校验服务器 TLS 证书。")+"\n密码仅用于当前连接，不保存密码。"
  alert.window.appearance=NSAppearance(named:.darkAqua);alert.addButton(withTitle:"连接");alert.addButton(withTitle:"取消")
  let field=NSSecureTextField(frame:NSRect(x:0,y:0,width:340,height:28));AppTheme.field(field);field.placeholderString="密码（匿名登录可留空）";field.setAccessibilityLabel("FTP 密码");field.stringValue="";alert.accessoryView=field;alert.window.initialFirstResponder=field
  return (alert,field)
 }
 static func ask(_ session:Session)->FTPCredentialChoice? {
  let prompt=makePrompt(session);defer{prompt.field.stringValue=""}
  guard prompt.alert.runModal() == .alertFirstButtonReturn else{return nil}
  return FTPCredentialChoice(password:prompt.field.stringValue)
 }
}

