 func reconnectFTP(_ value:FTPCredentialChoice){guard canManageFTPFiles,confirmEditorClose(),canManageFTPFiles else{return};closeTextEditors();connectionGeneration=UUID();hasAuthenticated=false;password=value.password;load(remotePath)}
 @objc func cancelFTP(){if transferQueue.active != nil{transferQueue.cancel()}else{cancelCurrentFTP()}}
