 var hasPendingFTPUpload:Bool {uploadProposal != nil}
 func prepareFTPUpload(_ urls:[URL])->FTPUploadProposal? {
  guard canManageFTPFiles else{return nil}
  do {let jobs=try FTPBatch.uploads(urls,directory:remotePath)
   guard transferQueue.jobs.count+jobs.count<=1000 else{throw SFTPError.message("传输队列最多 1000 项，请先清除已完成项目")}
   let proposal=FTPUploadProposal(directory:remotePath,operation:request,jobs:jobs);uploadProposal=proposal;updateControls();return proposal
  }catch{status.stringValue=error.localizedDescription;status.toolTip=status.stringValue;return nil}
 }
 @discardableResult func reviewFTPUpload(_ proposal:FTPUploadProposal,confirm:((FTPUploadProposal)->Bool)?=nil,showQueue:Bool=true)->Bool {
  guard uploadProposal?.id==proposal.id else{return false}
  defer{if uploadProposal?.id==proposal.id{uploadProposal=nil};updateControls();status.toolTip=status.stringValue}
  func current()->Bool {!busy && !stopped && transferQueue.active==nil && request==proposal.operation && Data(remotePath.utf8)==Data(proposal.directory.utf8)}
  guard current() else{status.stringValue="目录或连接状态已变化，未上传；请重新选择或拖入。";return false}
  let accepted:Bool
  if let confirm=confirm ?? confirmUpload {accepted=confirm(proposal)}
  else{let alert=proposal.makeAlert();uploadAlert=alert;accepted=alert.runModal() == .alertFirstButtonReturn;uploadAlert=nil}
  guard !stopped else{return false}
  guard accepted else{status.stringValue="已取消上传";return false}
  guard current(),transferQueue.jobs.count+proposal.jobs.count<=1000 else{status.stringValue="目录、连接或队列已变化，未上传；请重新选择或拖入。";return false}
  uploadProposal=nil;enqueueFTPJobs(proposal.jobs,showQueue:showQueue);return true
 }
 @objc func upload(){guard canManageFTPFiles else{return};let picker=NSOpenPanel();picker.canChooseDirectories=true;picker.canChooseFiles=true;picker.allowsMultipleSelection=true;picker.message="选择文件或文件夹；目录包含隐藏文件与空目录。";guard picker.runModal() == .OK,let proposal=prepareFTPUpload(picker.urls) else{return};reviewFTPUpload(proposal)}
 func uploadFile(_ source:URL,to destination:String){enqueueFTPJobs([TransferJob(local:source,remote:destination,uploading:true,allowOverwrite:true)])}
 @objc func download(){guard canManageFTPFiles,!selectedFTPFiles.isEmpty,selectedFTPFiles.allSatisfy({FTPBatch.canDownload($0)}) else{return};let chosen=selectedFTPFiles,directory=remotePath
  if chosen.count==1 && !chosen[0].directory {let picker=NSSavePanel();picker.nameFieldStringValue=chosen[0].name;guard picker.runModal() == .OK,let destination=picker.url,let source=try? FTPPath.child(chosen[0].name,in:directory) else{return};downloadFile(source,to:destination)}
  else{let picker=NSOpenPanel();picker.canChooseFiles=false;picker.canChooseDirectories=true;picker.canCreateDirectories=true;picker.message="选择保存位置。文件和目录加入下载队列；已有同名项目不会被覆盖。目录全部成功后才会出现。";guard picker.runModal() == .OK,let destination=picker.url else{return};enqueueFTPDownloads(chosen,from:directory,to:destination,showQueue:true)}
 }
 func downloadFile(_ source:String,to destination:URL){enqueueFTPJobs([TransferJob(local:destination,remote:source,uploading:false,allowOverwrite:true)])}

}
extension AppDelegate {
 @objc func newFTPSession(){ftpForm(index:nil)}
 func ftpForm(index:Int?){let old=index.map{sessions[$0]} ?? Session(name:"",host:"",user:NSUserName(),port:21,key:"",connectionTimeout:15,id:UUID(),group:sessionBrowser.selectedGroup,kind:.ftp,ftp:FTPSettings());guard let value=FTPEditor(session:old).run() else{return};let before=sessions;if let index=index{sessions[index]=value}else{sessions.append(value)};if !persist(){sessions=before;sessionBrowser.reload(sessions)}}
 func openFTP(_ input:Session){do{_ = try input.validatedFTP();guard let choice=FTPPassword.ask(input) else{return};_ = try FTPClient(session:input,password:choice.password);let session=recordRecent(input);let item=NSTabViewItem(identifier:UUID().uuidString);item.label=session.name;item.view=FTPWorkspace(session:session,password:choice.password);tabs.addTabViewItem(item);tabs.selectTabViewItem(item);updateTabStrip()}catch{alert(error.localizedDescription)}}
}
